#include <bits/stdc++.h>
using namespace std;

const int INF = 0x3f3f3f3f;
const int MAXN = 410;
const int MAXM = 200020;
const int GS = 12;
const int mx[4] = {-1, 0, 1, 0};
const int my[4] = {0, 1, 0, -1};

template <int V, int E>
struct Dinic {
    int head[V], to[E], nxt[E], cap[E], flow[E], ecnt, s, t;
    int level[V], cur[V];

    void init() {
        memset(head, -1, sizeof(head));
        ecnt = 0;
    }

    void addEdge(int u, int v, int c) {
        to[ecnt] = v;
        nxt[ecnt] = head[u];
        cap[ecnt] = c;
        flow[ecnt] = 0;
        head[u] = ecnt++;

        to[ecnt] = u;
        nxt[ecnt] = head[v];
        cap[ecnt] = 0;
        flow[ecnt] = 0;
        head[v] = ecnt++;
    }

    bool bfs() {
        memset(level, -1, sizeof(level));
        queue<int> q;
        level[s] = 0;
        q.push(s);
        while (!q.empty()) {
            int u = q.front();
            q.pop();
            for (int e = head[u]; e != -1; e = nxt[e]) {
                int v = to[e];
                if (level[v] == -1 && cap[e] > flow[e]) {
                    level[v] = level[u] + 1;
                    q.push(v);
                }
            }
        }
        return level[t] != -1;
    }

    int dfs(int u, int a) {
        if (u == t || a == 0) return a;
        int ret = 0;
        for (int &e = cur[u]; e != -1; e = nxt[e]) {
            int v = to[e];
            if (level[v] == level[u] + 1 && cap[e] > flow[e]) {
                int f = dfs(v, min(a, cap[e] - flow[e]));
                if (f > 0) {
                    flow[e] += f;
                    flow[e ^ 1] -= f;
                    a -= f;
                    ret += f;
                    if (a == 0) break;
                }
            }
        }
        return ret;
    }

    int maxflow(int S, int T) {
        s = S;
        t = T;
        int ans = 0;
        while (bfs()) {
            memcpy(cur, head, sizeof(head));
            ans += dfs(s, INF);
        }
        return ans;
    }
};

char gridA[MAXN][MAXN], gridB[MAXN][MAXN];
int safeTime[GS][GS], fastTime[GS][GS];
int n, timeLimit;

bool inside(int x, int y) {
    return x >= 0 && x < n && y >= 0 && y < n;
}

void zombieBfs(int sx, int sy) {
    memset(safeTime, 0x3f, sizeof(safeTime));
    queue<int> q;
    q.push(sx * 10 + sy);
    safeTime[sx][sy] = 0;
    while (!q.empty()) {
        int x = q.front() / 10, y = q.front() % 10;
        q.pop();
        for (int k = 0; k < 4; ++k) {
            int nx = x + mx[k], ny = y + my[k];
            if (inside(nx, ny) && gridA[nx][ny] >= '0' && gridA[nx][ny] <= '9' && safeTime[nx][ny] > safeTime[x][y] + 1) {
                safeTime[nx][ny] = safeTime[x][y] + 1;
                q.push(nx * 10 + ny);
            }
        }
    }
}

void playerBfs(int sx, int sy) {
    memset(fastTime, 0x3f, sizeof(fastTime));
    queue<int> q;
    q.push(sx * 10 + sy);
    fastTime[sx][sy] = 0;
    while (!q.empty()) {
        int x = q.front() / 10, y = q.front() % 10;
        q.pop();
        for (int k = 0; k < 4; ++k) {
            int nx = x + mx[k], ny = y + my[k];
            if (inside(nx, ny) && gridB[nx][ny] >= '0' && gridB[nx][ny] <= '9' && fastTime[nx][ny] > fastTime[x][y] + 1) {
                if (safeTime[nx][ny] >= fastTime[x][y] + 1) {
                    fastTime[nx][ny] = fastTime[x][y] + 1;
                    if (safeTime[nx][ny] > fastTime[nx][ny])
                        q.push(nx * 10 + ny);
                }
            }
        }
    }
}

int main() {
    scanf("%d%d", &n, &timeLimit);
    for (int i = 0; i < n; ++i) scanf("%s", gridA[i]);
    for (int i = 0; i < n; ++i) scanf("%s", gridB[i]);

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (gridA[i][j] == 'Z')
                zombieBfs(i, j);

    int S = 0, T = n * n * 2 + 1;
    static Dinic<MAXN, MAXM> flow;
    flow.init();

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j) {
            if (gridA[i][j] > '0' && gridA[i][j] <= '9')
                flow.addEdge(S, i * n + j + 1, gridA[i][j] - '0');
            if (gridB[i][j] > '0' && gridB[i][j] <= '9')
                flow.addEdge(n * n + i * n + j + 1, T, gridB[i][j] - '0');
        }

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (gridA[i][j] > '0' && gridA[i][j] <= '9') {
                playerBfs(i, j);
                for (int x = 0; x < n; ++x)
                    for (int y = 0; y < n; ++y)
                        if (gridB[x][y] > '0' && gridB[x][y] <= '9' && fastTime[x][y] <= timeLimit)
                            flow.addEdge(i * n + j + 1, n * n + x * n + y + 1, INF);
            }

    printf("%d\n", flow.maxflow(S, T));
    return 0;
}
